import { useState, type JSX } from 'react';

const code = `function MyComponent(props) {
	return (
	  <div>
		<h1>Hello, {props.name}!</h1>
		<p>Good to see you</p>
	  </div>
	);
  }`;

const codeTs = `function MyComponent(props: Props) {
	return (
	  <div>
		<h1>Hello, {props.name}!</h1>
		<p>Good to see you</p>
	  </div>
	);
  }`;

const codeLua = `local b64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local decode_table = ffi.new 'uint8_t[256]'
for i = 1, #b64 do
  decode_table[str_byte(b64, i)] = i - 1 -- Base64 values start from 0
end

function BloomFilter:has(key)
  local ptr = self.ptr -- uint8_t* pointer to start of base64 string
  for byte_offset, bit_offset in self:iterator(key) do
    local sextet = decode_table[ptr[byte_offset]]
    if band(sextet, lshift(1, bit_offset)) == 0 then
      return false
    end
  end
  return true
end`;

const languages = [
  {
    label: 'JavaScript',
    value: 'js',
  },
  {
    label: 'TypeScript',
    value: 'ts',
  },
  {
    label: 'Next.js',
    value: 'next',
  },
  {
    label: 'Lua',
    value: 'lua',
  },
];

export function Component(): JSX.Element {
  const [language, setLanguage] = useState('js');

  if (language === 'ts') {
    return (
      <CodeBlock
        aria-label="Hello world"
        filename="language-switcher.tsx"
        language="tsx"
        switcher={{
          options: languages,
          value: language,
          onChange: (l) => setLanguage(l),
        }}
      >
        {codeTs}
      </CodeBlock>
    );
  }

  if (language === 'next') {
    return (
      <CodeBlock
        aria-label="Hello world"
        filename="language-switcher.tsx"
        language="next"
        switcher={{
          options: languages,
          value: language,
          onChange: (l) => setLanguage(l),
        }}
      >
        {codeTs}
      </CodeBlock>
    );
  }

  if (language === 'lua') {
    return (
      <CodeBlock
        aria-label="Hello world"
        filename="bloom-filter.lua"
        language="lua"
        switcher={{
          options: languages,
          value: language,
          onChange: (l) => setLanguage(l),
        }}
      >
        {codeLua}
      </CodeBlock>
    );
  }

  return (
    <CodeBlock
      aria-label="Hello world"
      filename="language-switcher.jsx"
      language="jsx"
      switcher={{
        options: languages,
        value: language,
        onChange: (l) => setLanguage(l),
      }}
    >
      {code}
    </CodeBlock>
  );
}

